solution.javascript:
function interpolerMesures(vitesses, mini, maxi) {
  const valide = (v) => v >= mini && v <= maxi;
  const n = vitesses.length;
  const resultat = [...vitesses];
  let avant = -1;
  let i = 0;
  while (i < n) {
    if (valide(vitesses[i])) {
      avant = i;
      i++;
      continue;
    }
    let apres = i;
    while (apres < n && !valide(vitesses[apres])) {
      apres++;
    }
    for (let p = i; p < apres; p++) {
      if (avant === -1 && apres === n) {
        resultat[p] = mini;
      } else if (avant === -1) {
        resultat[p] = vitesses[apres];
      } else if (apres === n) {
        resultat[p] = vitesses[avant];
      } else {
        const a = vitesses[avant];
        const b = vitesses[apres];
        const pas = Math.floor((Math.abs(b - a) * (p - avant)) / (apres - avant));
        resultat[p] = b >= a ? a + pas : a - pas;
      }
    }
    i = apres;
  }
  return resultat;
}

solution.python:
def interpoler_mesures(vitesses, mini, maxi):
    def valide(v):
        return mini <= v <= maxi

    n = len(vitesses)
    resultat = list(vitesses)
    avant = -1
    i = 0
    while i < n:
        if valide(vitesses[i]):
            avant = i
            i += 1
            continue
        apres = i
        while apres < n and not valide(vitesses[apres]):
            apres += 1
        for p in range(i, apres):
            if avant == -1 and apres == n:
                resultat[p] = mini
            elif avant == -1:
                resultat[p] = vitesses[apres]
            elif apres == n:
                resultat[p] = vitesses[avant]
            else:
                a = vitesses[avant]
                b = vitesses[apres]
                pas = abs(b - a) * (p - avant) // (apres - avant)
                resultat[p] = a + pas if b >= a else a - pas
        i = apres
    return resultat

